    ctx.lineTo(ux+Math.cos(a0+2.3)*ar*0.9,uy+Math.sin(a0+2.3)*ar*0.9);
    ctx.lineTo(ux+Math.cos(a0-2.3)*ar*0.9,uy+Math.sin(a0-2.3)*ar*0.9);
